// Flatten the nested response so downstream nodes use $json.fieldName directly.
const rg   = $input.first().json;
const cafe = rg.cafe;

// Detect region for routing
const GCC_COUNTRIES    = ['UAE','Saudi Arabia','Qatar','Kuwait','Bahrain','Oman'];
const NORTH_AFRICA     = ['Morocco','Algeria','Tunisia','Libya','Egypt'];

const region =
  GCC_COUNTRIES.includes(cafe.country)  ? 'GCC'         :
  NORTH_AFRICA.includes(cafe.country)   ? 'NORTH_AFRICA' :
                                          'OTHER';

// Build caption variants
const stars = '⭐'.repeat(rg.rating);
const baseCaption = `${stars} ${rg.reviewText || 'تجربة رائعة!'}`;

return [{
  json: {
    reviewGalleryId    : rg.id,
    cafeId             : rg.cafeId,
    imageUrl           : rg.imageUrl || null,
    qrCodeUrl          : rg.qrCodeUrl || null,
    reviewText         : rg.reviewText,
    rating             : rg.rating,
    userConsentGranted : rg.userConsentGranted,

    cafeName           : cafe.name,
    city               : cafe.city,
    country            : cafe.country,
    packageType        : cafe.packageType,
    isArtisticQrPaid   : cafe.isArtisticQrPaid,
    logoAccentColor    : cafe.logoAccentColor,

    // Social media credentials (stored encrypted in Cafe doc)
    fbPageId           : cafe.fbPageId           || null,
    fbAccessToken      : cafe.fbAccessToken       || null,
    igUserId           : cafe.igUserId            || null,
    tiktokAccessToken  : cafe.tiktokAccessToken   || null,
    snapAccessToken    : cafe.snapAccessToken     || null,

    region,
    baseCaption,
    isPaidTier         : ['6-Month','Annual'].includes(cafe.packageType)
  }
}];

// ─── NORTH AFRICA: Facebook Page Post + Instagram Reel/Post ────────────────
// Facebook Graph API v19
const d = $input.first().json;

const photoUrl    = d.imageUrl || d.qrCodeUrl;
const caption     = `${d.baseCaption}\n\n📍 ${d.cafeName}, ${d.city}\n#${d.city.replace(/\s+/g,'')} #SmartResto #مطعم_${d.city.replace(/\s+/g,'_')}`;

return [{ json: { ...d, fbCaption: caption, fbPhotoUrl: photoUrl } }];

// ─── GCC: TikTok + Snapchat ─────────────────────────────────────────────────
const d = $input.first().json;

const caption = `${d.baseCaption} ✨\n#${d.city.replace(/\s+/g,'')} #مطعم #SmartResto #food #${d.cafeName.replace(/\s+/g,'')}`;

return [{ json: { ...d, gccCaption: caption } }];

// ─── Other regions: Instagram only (fallback) ───────────────────────────────
const d = $input.first().json;
const caption = `${d.baseCaption}\n\n📍 ${d.cafeName}, ${d.city}\n#${d.city.replace(/\s+/g,'')} #SmartResto #food`;
return [{ json: { ...d, igFallbackCaption: caption } }];

// ─── FREE TIER: Post to Smart Resto Official Channels ───────────────────────
// Auto-generate SEO-optimised caption + keywords.
const d = $input.first().json;

const year       = new Date().getFullYear();
const citySlug   = d.city.replace(/\s+/g, '-').toLowerCase();
const cityHashtag = '#' + d.city.replace(/\s+/g, '');
const cafeHashtag = '#' + d.cafeName.replace(/\s+/g, '');

const seoKeywords = [
  `Best restaurant in ${d.city} ${year}`,
  `${d.cafeName} ${d.city} review`,
  `Top rated food ${d.city}`,
  `مطعم ${d.city}`,
  `أفضل مطعم في ${d.city}`
];

const blogTitle = `${d.cafeName} — تقييم موثق بـ Smart Resto | ${d.city} ${year}`;

const officialCaption =
  `⭐ ${'⭐'.repeat(d.rating - 1)} تقييم موثق في ${d.cafeName}\n` +
  `📍 ${d.city}\n\n` +
  `"${d.reviewText?.slice(0, 120) || 'تجربة رائعة!'}"\n\n` +
  `${cityHashtag} ${cafeHashtag} #SmartResto #مطعم #food #${citySlug}`;

const twitterPost =
  `⭐ تقييم جديد في ${d.cafeName} — ${d.city}\n` +
  `"${d.reviewText?.slice(0, 100) || 'تجربة رائعة!'}"\n` +
  `#SmartResto ${cityHashtag}`;

return [{
  json: {
    ...d,
    seoKeywords,
    blogTitle,
    officialCaption,
    twitterPost,
    blogSlug: `${citySlug}-${d.cafeName.replace(/\s+/g,'-').toLowerCase()}-${Date.now()}`
  }
}];

// Build update payload depending on which path ran.
// $input.first().json may come from any of the 4 branches.
// Use $('Code — Flatten & Detect Region') to get the stable base data.
const base = $('Code — Flatten & Detect Region').first().json;

return [{
  json: {
    reviewGalleryId               : base.reviewGalleryId,
    cafeId                        : base.cafeId,
    isPublishedToClientSocial     : base.isPaidTier,
    publishedToClientSocialAt     : base.isPaidTier ? new Date().toISOString() : null,
    isPublishedToSmartRestoBlog   : !base.isPaidTier,
    publishedToSmartRestoBlogAt   : !base.isPaidTier ? new Date().toISOString() : null,
    moderationStatus              : 'approved',
    n8nExecutionId                : $execution.id
  }
}];
